import React, { useState, useRef, useCallback, useEffect } from "react";
import ForceGraph2D from "react-force-graph";
import axios from "axios";
import "./App.css";

const API = "http://localhost:8000";

// ─── Color helpers ───────────────────────────────────────────────────────────
const riskColor = (score, isRoot) => {
  if (isRoot) return "#f4d03f";
  if (score >= 0.65) return "#e74c3c";
  if (score >= 0.35) return "#e67e22";
  return "#27ae60";
};

const riskBadgeClass = (level) =>
  ({ HIGH: "badge-high", MEDIUM: "badge-med", LOW: "badge-low" }[level] || "badge-unknown");

const shortenAddr = (addr) =>
  addr ? `${addr.slice(0, 6)}…${addr.slice(-4)}` : "—";

const formatEth = (val) =>
  val !== undefined && val !== null ? `${Number(val).toFixed(4)} ETH` : "—";

// ─── Component: NodePanel ────────────────────────────────────────────────────
function NodePanel({ node, onRetrace }) {
  if (!node) return null;
  return (
    <div className="node-panel">
      <div className="panel-title">
        <span className="panel-icon">🔍</span> Wallet Details
        {node.isSupernode && (
          <span className="supernode-badge">EXCHANGE / HIGH-VOLUME</span>
        )}
      </div>
      <div className="panel-addr" title={node.address}>
        {node.address}
      </div>
      <div className="panel-row">
        <span>Dirty Score</span>
        <span>
          <span
            className={`badge ${riskBadgeClass(node.riskLevel)}`}
          >
            {node.riskLevel}
          </span>{" "}
          {(node.dirtyScore * 100).toFixed(1)}%
        </span>
      </div>
      <div className="panel-score-bar">
        <div
          className="panel-score-fill"
          style={{
            width: `${node.dirtyScore * 100}%`,
            background: riskColor(node.dirtyScore, false),
          }}
        />
      </div>
      <div className="panel-row">
        <span>ETH Balance</span>
        <span>{formatEth(node.ethBalance)}</span>
      </div>
      <div className="panel-row">
        <span>Total Sent</span>
        <span>{formatEth(node.totalSent)}</span>
      </div>
      <div className="panel-row">
        <span>Total Received</span>
        <span>{formatEth(node.totalReceived)}</span>
      </div>
      <div className="panel-row">
        <span>Tx Count</span>
        <span>{node.txCount?.toLocaleString()}</span>
      </div>
      <div className="panel-row">
        <span>Hop Depth</span>
        <span>{node.depth}</span>
      </div>
      <button
        className="retrace-btn"
        onClick={() => onRetrace(node.address)}
        disabled={node.isSupernode}
        title={node.isSupernode ? "Supernodes are not recursed" : ""}
      >
        Trace from this wallet →
      </button>
    </div>
  );
}

// ─── Component: Legend ───────────────────────────────────────────────────────
function Legend() {
  return (
    <div className="legend">
      <div className="legend-title">Risk Legend</div>
      <div className="legend-row">
        <span className="dot" style={{ background: "#f4d03f" }} /> Root Wallet
      </div>
      <div className="legend-row">
        <span className="dot" style={{ background: "#27ae60" }} /> Low Risk (&lt;35%)
      </div>
      <div className="legend-row">
        <span className="dot" style={{ background: "#e67e22" }} /> Medium Risk (35–65%)
      </div>
      <div className="legend-row">
        <span className="dot" style={{ background: "#e74c3c" }} /> High Risk (&gt;65%)
      </div>
      <div className="legend-row">
        <span className="dot" style={{ background: "#9b59b6", border: "2px dashed #fff" }} />{" "}
        Exchange / Supernode
      </div>
    </div>
  );
}

// ─── Component: MetaBar ──────────────────────────────────────────────────────
function MetaBar({ meta, loading }) {
  if (loading) return <div className="meta-bar pulsing">Tracing… please wait</div>;
  if (!meta) return null;
  return (
    <div className="meta-bar">
      <span>🔗 {meta.nodeCount} wallets</span>
      <span>↔ {meta.linkCount} txs</span>
      <span>⏱ {meta.elapsedSeconds}s</span>
      <span>📏 Max depth {meta.maxDepthReached}</span>
    </div>
  );
}

// ─── Main App ─────────────────────────────────────────────────────────────────
export default function App() {
  const [address, setAddress]   = useState("");
  const [maxDepth, setMaxDepth] = useState(5);
  const [maxNodes, setMaxNodes] = useState(200);
  const [minScore, setMinScore] = useState(0);     // filter
  const [graphData, setGraphData] = useState({ nodes: [], links: [] });
  const [filteredGraph, setFilteredGraph] = useState({ nodes: [], links: [] });
  const [meta, setMeta]         = useState(null);
  const [loading, setLoading]   = useState(false);
  const [error, setError]       = useState("");
  const [selectedNode, setSelectedNode] = useState(null);
  const fgRef = useRef();

  // ─── Filter ──────────────────────────────────────────────────────────────
  useEffect(() => {
    const nodeIds = new Set(
      graphData.nodes
        .filter((n) => n.dirtyScore >= minScore || n.isRoot)
        .map((n) => n.id)
    );
    setFilteredGraph({
      nodes: graphData.nodes.filter((n) => nodeIds.has(n.id)),
      links: graphData.links.filter(
        (l) => nodeIds.has(l.source?.id || l.source) && nodeIds.has(l.target?.id || l.target)
      ),
    });
  }, [graphData, minScore]);

  // ─── Trace ────────────────────────────────────────────────────────────────
  const doTrace = useCallback(async (addr) => {
    const a = (addr || address).trim().toLowerCase();
    if (!a.startsWith("0x") || a.length !== 42) {
      setError("Invalid Ethereum address. Must start with 0x and be 42 chars.");
      return;
    }
    setError("");
    setLoading(true);
    setSelectedNode(null);
    setGraphData({ nodes: [], links: [] });
    setMeta(null);
    try {
      const { data } = await axios.post(`${API}/trace`, {
        address: a,
        maxDepth,
        maxNodes,
      });
      setGraphData({ nodes: data.nodes, links: data.links });
      setMeta(data.meta);
    } catch (err) {
      setError(err?.response?.data?.detail || err.message || "Trace failed.");
    } finally {
      setLoading(false);
    }
  }, [address, maxDepth, maxNodes]);

  // ─── Graph callbacks ─────────────────────────────────────────────────────
  const nodeColor = useCallback(
    (n) => (n.isSupernode ? "#9b59b6" : riskColor(n.dirtyScore, n.isRoot)),
    []
  );
  const nodeVal = useCallback(
    (n) => Math.max(3, (n.txCount || 1) / 10 + (n.dirtyScore || 0) * 8),
    []
  );
  const linkWidth = useCallback(
    (l) => Math.max(0.5, Math.log10((l.value || 0.0001) + 1) * 1.5),
    []
  );
  const linkColor = useCallback(() => "rgba(100,120,150,0.3)", []);
  const onNodeClick = useCallback((n) => setSelectedNode(n), []);

  return (
    <div className="app">
      {/* ── Sidebar ─────────────────────────────────────────────────── */}
      <aside className="sidebar">
        <div className="logo">
          <span className="logo-icon">⛓</span>
          <span className="logo-text">CryptoTrace</span>
        </div>
        <div className="sidebar-label">Wallet Address</div>
        <input
          className="addr-input"
          value={address}
          onChange={(e) => setAddress(e.target.value)}
          placeholder="0x…"
          onKeyDown={(e) => e.key === "Enter" && doTrace()}
        />

        <div className="controls-row">
          <label>
            <span>Depth</span>
            <input
              type="number"
              min={1}
              max={10}
              value={maxDepth}
              onChange={(e) => setMaxDepth(Number(e.target.value))}
            />
          </label>
          <label>
            <span>Max Nodes</span>
            <input
              type="number"
              min={10}
              max={500}
              step={10}
              value={maxNodes}
              onChange={(e) => setMaxNodes(Number(e.target.value))}
            />
          </label>
        </div>

        <button
          className="trace-btn"
          onClick={() => doTrace()}
          disabled={loading}
        >
          {loading ? "Tracing…" : "▶ Trace Wallet"}
        </button>

        {error && <div className="error-msg">{error}</div>}

        <div className="divider" />

        <div className="sidebar-label">Filter by Min Risk Score</div>
        <input
          type="range"
          min={0}
          max={0.9}
          step={0.05}
          value={minScore}
          onChange={(e) => setMinScore(Number(e.target.value))}
        />
        <div className="filter-val">{(minScore * 100).toFixed(0)}%</div>

        <div className="divider" />
        <Legend />
        <div className="divider" />

        <NodePanel node={selectedNode} onRetrace={doTrace} />
      </aside>

      {/* ── Main canvas ─────────────────────────────────────────────── */}
      <main className="canvas-area">
        <MetaBar meta={meta} loading={loading} />

        {filteredGraph.nodes.length === 0 && !loading && (
          <div className="empty-state">
            <div className="empty-icon">🔗</div>
            <div>Enter an Ethereum wallet address and press <strong>Trace Wallet</strong></div>
            <div className="empty-sub">
              The forensic engine will map up to {maxNodes} connected wallets
              across {maxDepth} hops and score each one for suspicious activity.
            </div>
          </div>
        )}

        <ForceGraph2D
          ref={fgRef}
          graphData={filteredGraph}
          nodeId="id"
          nodeColor={nodeColor}
          nodeVal={nodeVal}
          nodeLabel={(n) =>
            `${shortenAddr(n.address)} | Score: ${(n.dirtyScore * 100).toFixed(1)}% | ${n.riskLevel}`
          }
          linkWidth={linkWidth}
          linkColor={linkColor}
          linkDirectionalArrowLength={4}
          linkDirectionalArrowRelPos={1}
          onNodeClick={onNodeClick}
          backgroundColor="#0a0e1a"
          width={window.innerWidth - 320}
          height={window.innerHeight - 48}
          cooldownTicks={100}
          nodeCanvasObject={(node, ctx, globalScale) => {
            const r = Math.max(3, nodeVal(node));
            // Glow for high-risk nodes
            if (node.dirtyScore >= 0.65) {
              ctx.beginPath();
              ctx.arc(node.x, node.y, r + 4, 0, 2 * Math.PI);
              ctx.fillStyle = "rgba(231,76,60,0.18)";
              ctx.fill();
            }
            ctx.beginPath();
            ctx.arc(node.x, node.y, r, 0, 2 * Math.PI);
            ctx.fillStyle = nodeColor(node);
            ctx.fill();
            if (node.isRoot) {
              ctx.strokeStyle = "#fff";
              ctx.lineWidth = 2;
              ctx.stroke();
            }
            // Label at zoom > 2
            if (globalScale > 2) {
              ctx.font = `${10 / globalScale}px monospace`;
              ctx.fillStyle = "#fff";
              ctx.textAlign = "center";
              ctx.fillText(shortenAddr(node.address), node.x, node.y + r + 8 / globalScale);
            }
          }}
        />
      </main>
    </div>
  );
}
